"""Ask for a topic, then print a data analytics joke generated by Gemini on Vertex AI.

Uses the service-account credentials in creds.json (next to this script).
Usage: python main.py [--model gemini-2.5-flash] [--location us-central1]
"""
import argparse
import json
import os
import random
from pathlib import Path

from google import genai
from google.genai import types
from google.oauth2 import service_account

CREDS_PATH = Path(__file__).with_name("creds.json")
TOPICS = [
    "SQL joins", "pivot tables", "a dashboard nobody reads", "p-values", "correlation vs causation",
    "missing data", "a machine learning model", "Excel", "big data", "data cleaning",
    "outliers", "A/B testing", "a data warehouse", "overfitting", "a bar chart vs a pie chart",
]


def make_client(location="us-central1"):
    # In GitHub Actions the key comes from a secret instead of creds.json.
    info = json.loads(os.environ.get("GCP_CREDENTIALS") or CREDS_PATH.read_text())
    project_id = info["project_id"]
    credentials = service_account.Credentials.from_service_account_info(
        info, scopes=["https://www.googleapis.com/auth/cloud-platform"]
    )
    return genai.Client(
        vertexai=True, project=project_id, location=location, credentials=credentials
    )


def generate_joke(client, topic="", model="gemini-2.5-flash"):
    """Return (topic, joke); a blank topic picks a random one."""
    topic = topic.strip() or random.choice(TOPICS)
    response = client.models.generate_content(
        model=model,
        contents=f"Tell me a short, original joke about data analytics, themed on {topic}. "
                 "Reply with only the joke.",
        config=types.GenerateContentConfig(
            temperature=1.2,
            max_output_tokens=500,
            # Thinking tokens count toward max_output_tokens and can truncate the joke.
            thinking_config=types.ThinkingConfig(thinking_budget=0),
        ),
    )
    return topic, response.text.strip()


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--model", default="gemini-2.5-flash")
    parser.add_argument("--location", default="us-central1")
    args = parser.parse_args()

    client = make_client(args.location)
    topic = input("What topic do you like? (press Enter for a random one): ")
    topic, joke = generate_joke(client, topic, args.model)
    print(f"[{topic}] {joke}")


if __name__ == "__main__":
    main()
